def _f(current, candidates, tour, start):
    """Global centrality: mean distance from each candidate to all other unvisited cities (how deeply it sits inside the remaining cloud), normalised."""
    k = len(candidates)
    if k <= 1:
        return np.zeros(k)
    d = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=-1)
    mean_other = d.sum(axis=1) / (k - 1)
    return mean_other / (np.max(mean_other) + 1e-9)

_TERMS = [(_f, np.array([1.0]))]

def priority(current, candidates, tour, start):
    total = None
    for f, w in _TERMS:
        v = np.asarray(f(current, candidates, tour, start), dtype=float)
        v = v[:, None] if v.ndim == 1 else v
        total = (np.zeros(len(v)) if total is None else total) + v[:, :len(w)] @ w[:v.shape[1]]
