import numpy as np


def feature(current, candidates, tour, start):
    """Postpone cost of a candidate: min(nearest other unvisited city distance, distance to start) minus distance from current."""
    c = candidates
    k = c.shape[0]
    if k == 0:
        return np.zeros(0)
    if k == 1:
        return np.zeros(1)

    d_cur = np.sqrt(np.sum((c - current) ** 2, axis=1))
    dh = np.sqrt(np.sum((c - start) ** 2, axis=1))

    diff = c[:, None, :] - c[None, :, :]
    pair = np.sqrt(np.sum(diff ** 2, axis=2))
    np.fill_diagonal(pair, np.inf)
    nn = np.min(pair, axis=1)

    postpone = np.where(np.isfinite(nn), np.minimum(nn, dh), dh)
    v = postpone - d_cur

    return v / (np.max(np.abs(v)) + 1e-9)

