    """Negative tanh hinge of each candidate's current distance above the remaining cloud's median nearest-neighbour spacing."""
    c = np.asarray(candidates, dtype=float)
    k = c.shape[0]
    if k < 2:
        return np.zeros(k, dtype=float)

    d_cur = np.sqrt(np.sum((c - np.asarray(current, dtype=float)) ** 2, axis=1))

